	for _, line := range input {
		if err := f.evalLine(line); err != nil {
			return nil, err
		}
	}
	return f.stack, nil
}

// evalLine evaluates a single source line, executing words in order and
// handling word definitions (: name body ;).
func (f *forth) evalLine(line string) error {
	var defName string
	var defBody []op
	defining := false
	for _, field := range strings.Fields(line) {
		word := strings.ToLower(field)
		switch {
		case word == ":":
			defining = true
			defName = ""
			defBody = nil
		case defining:
			switch {
			case word == ";":
				if defName == "" {
					return errNoName
				}
				body := defBody
				f.defs[defName] = func(f *forth) error {
					for _, b := range body {
						if err := b(f); err != nil {
							return err
						}
					}
					return nil
				}
				defining = false
			case defName == "":
				if isNumber(word) {
					return errIllegalOp
				}
				defName = word
			default:
				bodyOp, err := f.resolve(word)
				if err != nil {
					return err
				}
				defBody = append(defBody, bodyOp)
			}
		default:
			if err := f.execWord(word); err != nil {
				return err
			}
		}
	}
	if defining {
		return errUnterminated
	}
	return nil
}

// execWord executes a single word in normal (non-definition) context:
// a number is pushed, any other word must exist in the dictionary.
func (f *forth) execWord(word string) error {
	if n, ok := parseNumber(word); ok {
		return f.push(n)
	}
	body, ok := f.defs[word]
	if !ok {
		return errUndefined
	}
	return body(f)
}

// resolve looks up a word for use inside a definition body. The body is
// resolved at definition time so that later redefinitions of the words
// it references do not change the behavior of the new definition.
func (f *forth) resolve(word string) (op, error) {
	if n, ok := parseNumber(word); ok {
		return func(f *forth) error { return f.push(n) }, nil
	}
	body, ok := f.defs[word]
	if !ok {
		return nil, errUndefined
	}
	return body, nil
}

// isNumber reports whether word is a number literal.
func isNumber(word string) bool {
	_, ok := parseNumber(word)
	return ok
}

// parseNumber parses a Forth number: an optional minus sign followed by
// one or more ASCII digits.
func parseNumber(word string) (int, bool) {
	i := 0
	if word[0:1] == "-" {
		i = 1
	}
	if i >= len(word) {
		return 0, false
	}
	for _, c := range word[i:] {
		if c < '0' || c > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(word)
	if err != nil {
		return 0, false
	}
	return n, true
}

func builtinDict() map[string]op {
	return map[string]op{
		"+":    (*forth).add,
		"-":    (*forth).sub,
		"*":    (*forth).mul,
		"/":    (*forth).div,
		"dup":  (*forth).dup,
		"drop": (*forth).drop,
		"swap": (*forth).swap,
		"over": (*forth).over,
	}
}

// push appends a value to the data stack.
func (f *forth) push(v int) error {
	f.stack = append(f.stack, v)
	return nil
}

// pop removes and returns the top of the stack.
func (f *forth) pop() (int, error) {
	if len(f.stack) == 0 {
		return 0, errEmptyStack
	}
	v := f.stack[len(f.stack)-1]
	f.stack = f.stack[:len(f.stack)-1]
	return v, nil
}

// pop2 removes and returns the top two values of the stack,
// returning the second-from-top first.
func (f *forth) pop2() (int, int, error) {
	switch len(f.stack) {
	case 0:
		return 0, 0, errEmptyStack
	case 1:
		return 0, 0, errOneValue
	}
	a := f.stack[len(f.stack)-2]
	b := f.stack[len(f.stack)-1]
	f.stack = f.stack[:len(f.stack)-2]
	return a, b, nil
}

func (f *forth) add() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	return f.push(a + b)
}

func (f *forth) sub() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	return f.push(a - b)
}

func (f *forth) mul() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	return f.push(a * b)
}

func (f *forth) div() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	if b == 0 {
		return errDivideByZero
	}
	return f.push(a / b)
}

func (f *forth) dup() error {
	v, err := f.pop()
	if err != nil {
		return err
	}
	f.stack = append(f.stack, v, v)
	return nil
}

func (f *forth) drop() error {
	_, err := f.pop()
	return err
}

func (f *forth) swap() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	f.stack = append(f.stack, b, a)
	return nil
}

func (f *forth) over() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	f.stack = append(f.stack, a, b, a)
	return nil
}
